STAMP_POS = 'right:70px;bottom:140px'

def slide(i, n, s):
    bg = s.get('bg', 'dark')
    top = f'<div class="top"><div class="brand" data-logo>Юридический иммунитет</div><div class="num">{i:02d}/{n:02d}</div></div>'
    body = ''
    if s.get('tag'):
        cls = s.get('tagcls', '')
        body += f'<span class="tag {cls}">{s["tag"]}</span>'
    if s.get('h1'):
        body += f'<h1 style="margin-top:40px;{s.get("h1style","")}">{s["h1"]}</h1>'
    if s.get('h2'):
        body += f'<h2 style="margin-top:{30 if s.get("tag") else 0}px">{s["h2"]}</h2>'
    for p in s.get('p', []):
        body += f'<p style="margin-top:26px">{p}</p>'
    if s.get('ol'):
        body += '<ol>' + ''.join(f'<li>{x}</li>' for x in s['ol']) + '</ol>'
    if s.get('box'):
        body += f'<div class="box"><p>{s["box"]}</p></div>'
    if s.get('pain'):
        k = s['pain']
        body += '<div class="pain">' + ''.join(f'<i class="{"on" if j < k else ""}"></i>' for j in range(5)) + f'<b>{k}/5</b></div><p class="small" style="margin-top:10px">Индекс боли</p>'
    stamp = ''
    if s.get('stamp'):
        txt, col = s['stamp']
        stamp = f'<div class="stamp st-{col}" style="{s.get("stamppos", STAMP_POS)}">{txt}</div>'
    foot = f'<div class="swipe">{s["swipe"]}</div>' if s.get('swipe') else ''
    if s.get('small'):
        foot += f'<div class="small">{s["small"]}</div>'
    return f'<section class="s {bg}" id="s{i}">{top}<div class="mid">{body}</div>{stamp}{foot}</section>'

